   ("=", "Para resolver 2x² = 72, ¿cuánto vale x² al dividir 72 entre 2?", "72//2", "Se divide por 2 para dejar x² solo."),
   Q("Las soluciones de x² − 25 = 0 son", "5 y −5", "25 y −25", "10 y −10", "Pasando 25 queda x² = 25, cuyas raíces son 5 y −5."),
   T2("{F} ¿La ecuación x² + 4 = 0 tiene solución con números reales?", "No: x² = −4 y ningún cuadrado es negativo", "Sí: x = 2", "Al elevar 2 al cuadrado se obtiene 4, no −4."),
