   Q("Resuelve (x − 4)(x + 1) = 0.", "x = 4 o x = −1", "x = −4 o x = 1", "x = 4 o x = 1", "x − 4 = 0 da x = 4 y x + 1 = 0 da x = −1."),
   Q("Factoriza y resuelve x² + 7x + 10 = 0.", "x = −2 o x = −5", "x = 2 o x = 5", "x = −7 o x = −10", "Los números 2 y 5 suman 7 y multiplican 10, así que (x + 2)(x + 5) = 0."),
